import { Group, Mesh, PlaneGeometry, CircleGeometry, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, SpotLight, AmbientLight } from 'three/webgpu';
import { uv, mix, smoothstep, vec3, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();
  group.name = 'divider-jewel';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const pal = {
    ink: new THREE.Color(colors.ink ?? '#16161d'),
    paper: new THREE.Color(colors.paper ?? '#e8ecf2'),
    accent: new THREE.Color(colors.accent ?? '#ff2a38'),
    surface: new THREE.Color(colors.surface ?? '#0b0b10'),
  };

  const disposables = [];
  const timelines = [];
  const lights = [];

  // ---- Stage backdrop plane with vertical gradient (spec stops) ----
  const backdropGeo = new PlaneGeometry(7, 6);
  disposables.push(backdropGeo);
  const backdropMat = new MeshStandardNodeMaterial();
  const gradT = uv().y;
  const gradCol = mix(
    vec3(pal.surface.r, pal.surface.g, pal.surface.b),
    vec3(pal.ink.r, pal.ink.g, pal.ink.b),
    smoothstep(0.0, 1.0, gradT)
  );
  backdropMat.colorNode = gradCol;
  backdropMat.roughnessNode = uniform(0.85);
  backdropMat.metalnessNode = uniform(0.0);
  disposables.push(backdropMat);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---- Local lights ----
  const ambient = new AmbientLight(pal.paper.getHex(), 0.4);
  group.add(ambient);

  const key = new SpotLight(0xffffff, 1.0, 12, Math.PI / 4, 0.5, 1.2);
  key.position.set(1.5, 1.8, 3.2);
  key.target.position.set(0, 0, 0);
  group.add(key);
  group.add(key.target);
  lights.push(key);

  const rim = new SpotLight(pal.accent.getHex(), 0.7, 12, Math.PI / 3, 0.6, 1.0);
  rim.position.set(-2.2, 0.4, 2.8);
  rim.target.position.set(0, 0, 0);
  group.add(rim);
  group.add(rim.target);
  lights.push(rim);

  // ---- Procedural divider rule + center jewel (fallback / acting geometry) ----
  const ruleContainer = new Group();
  group.add(ruleContainer);

  // Thin machined metal rule
  const ruleGeo = new THREE.BoxGeometry(3.4, 0.04, 0.06);
  disposables.push(ruleGeo);
  const ruleMat = new MeshPhysicalNodeMaterial();
  ruleMat.colorNode = vec3(0.55, 0.56, 0.6);
  ruleMat.metalnessNode = uniform(0.92);
  ruleMat.roughnessNode = uniform(0.32);
  ruleMat.clearcoatNode = uniform(0.2);
  ruleMat.clearcoatRoughnessNode = uniform(0.4);
  disposables.push(ruleMat);
  const ruleL = new Mesh(ruleGeo, ruleMat);
  ruleL.position.set(-1.15, 0, 0);
  ruleContainer.add(ruleL);

  const ruleR = new Mesh(ruleGeo, ruleMat);
  ruleR.position.set(1.15, 0, 0);
  ruleContainer.add(ruleR);

  // Center jewel — fluted bezel ring + faceted gem
  const bezelGeo = new THREE.TorusGeometry(0.12, 0.025, 16, 32);
  disposables.push(bezelGeo);
  const bezelMat = new MeshPhysicalNodeMaterial();
  bezelMat.colorNode = vec3(0.75, 0.76, 0.8);
  bezelMat.metalnessNode = uniform(0.95);
  bezelMat.roughnessNode = uniform(0.25);
  bezelMat.clearcoatNode = uniform(0.25);
  disposables.push(bezelMat);
  const bezel = new Mesh(bezelGeo, bezelMat);
  bezel.position.set(0, 0, 0.015);
  ruleContainer.add(bezel);

  // Gem stone — accent red, cut
  const gemGeo = new THREE.OctahedronGeometry(0.085, 0);
  disposables.push(gemGeo);
  const gemMat = new MeshPhysicalNodeMaterial();
  gemMat.colorNode = vec3(pal.accent.r, pal.accent.g, pal.accent.b);
  gemMat.metalnessNode = uniform(0.1);
  gemMat.roughnessNode = uniform(0.08);
  gemMat.transmissionNode = uniform(0.35);
  gemMat.iorNode = uniform(1.9);
  gemMat.thicknessNode = uniform(0.08);
  gemMat.emissiveNode = vec3(pal.accent.r * 0.6, pal.accent.g * 0.06, pal.accent.b * 0.06);
  gemMat.emissiveIntensityNode = uniform(0.9);
  disposables.push(gemMat);
  const gem = new Mesh(gemGeo, gemMat);
  gem.position.set(0, 0, 0.06);
  gem.rotation.set(0.4, 0.3, 0);
  ruleContainer.add(gem);

  // Contact shadow plane beneath jewel area
  const shadowGeo = new CircleGeometry(0.34, 32);
  disposables.push(shadowGeo);
  const shadowMat = new MeshStandardNodeMaterial();
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.transparent = true;
  shadowMat.opacity = 0.45;
  shadowMat.depthWrite = false;
  shadowMat.roughnessNode = uniform(1.0);
  shadowMat.metalnessNode = uniform(0.0);
  disposables.push(shadowMat);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.04, -0.02);
  ruleContainer.add(shadow);

  // ---- Load GLB mesh and swap in ----
  let glbRoot = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const root = (gltf && (gltf.scene || gltf)) || null;
      if (!root) return;
      glbRoot = root;
      root.traverse((o) => {
        if (o.isMesh) {
          o.castShadow = true;
          o.receiveShadow = true;
        }
      });
      ruleContainer.visible = false;
      group.add(root);
    }).catch(() => { /* keep procedural fallback */ });
  }

  // ---- Entrance motion ----
  group.scale.set(0.96, 0.96, 0.96);
  group.position.set(0, 0.15, 0);
  const enter = gsap.timeline();
  enter.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  enter.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power3.out' }, 0);
  enter.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' }, 0.55);
  enter.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.55, ease: 'power4.out' }, 0.9);
  enter.fromTo(group, { opacity: 0 }, { opacity: 1, duration: 0.4, ease: 'power2.out' }, 0);
  enter.pause();
  timelines.push(enter);
  requestAnimationFrame(() => enter.play());

  // ---- Idle breathing on gem ----
  const idle = gsap.to(gem.rotation, {
    y: '+=0.5',
    duration: 18,
    ease: 'sine.inOut',
    repeat: -1,
    yoyo: true,
  });
  timelines.push(idle);

  // ---- Event handlers ----
  const state = { hover: false, pressing: false };
  const hovers = [];

  function applyHover(on) {
    state.hover = on;
    const tl = gsap.timeline();
    const dy = on ? 0.15 : 0.0;
    tl.to(ruleContainer.position, { y: dy, duration: 0.4, ease: 'power2.out' }, 0);
    if (on) {
      tl.to(bezel.rotation, { z: '+=0.18', duration: 0.5, ease: 'power3.out' }, 0);
      tl.to(gemMat.emissiveIntensityNode, { value: 1.6, duration: 0.4, ease: 'power2.out' }, 0);
    } else {
      tl.to(gemMat.emissiveIntensityNode, { value: 0.9, duration: 0.5, ease: 'power2.out' }, 0);
    }
    hovers.push(tl);
    hovers.length && hovers.splice(0, hovers.length - 1);
  }

  function applyPress(down) {
    state.pressing = down;
    const target = down ? 0.97 : 1.0;
    gsap.to(group.scale, { x: target, y: target, z: target, duration: 0.12, ease: 'back.out(2)' });
  }

  group.userData.handlers = {
    onPointerEnter: () => applyHover(true),
    onPointerLeave: () => { if (state.pressing) applyPress(false); applyHover(false); },
    onPointerDown: (e) => { e.stopPropagation && e.stopPropagation(); applyPress(true); },
    onPointerUp: (e) => { applyPress(false); ctx.emit && ctx.emit('hub-home.select', { source: 'divider-jewel' }); },
    onClick: (e) => { e && e.stopPropagation && e.stopPropagation(); ctx.emit && ctx.emit('hub-home.select', { origin: group.name }); },
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((t) => { try { t.kill(); } catch (_) {} });
    hovers.forEach((t) => { try { t.kill(); } catch (_) {} });
    lights.forEach((l) => { try { l.dispose && l.dispose(); } catch (_) {} });
    disposables.forEach((d) => {
      try {
        if (d && typeof d.dispose === 'function') d.dispose();
      } catch (_) {}
    });
    if (glbRoot) {
      glbRoot.traverse((o) => {
        if (o.geometry) try { o.geometry.dispose(); } catch (_) {}
        if (o.material) {
          const mats = Array.isArray(o.material) ? o.material : [o.material];
          mats.forEach((m) => { try { m.dispose(); } catch (_) {} });
        }
      });
    }
  };

  return group;
}
